import{_ as c,o as r,c as t,a4 as i}from"./chunks/framework.DpieW3qv.js";const p=JSON.parse('{"title":"API Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/api/index.md","filePath":"reference/api/index.md","lastUpdated":null}'),a={name:"reference/api/index.md"};function s(o,e,n,d,l,u){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="api-reference" tabindex="-1">API Reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to &quot;API Reference&quot;">​</a></h1><p>API docs are generated from JSDoc. Run <code>make docs-build</code> to regenerate.</p><h2 id="ocapi-infrastructure" tabindex="-1">OCAPI Infrastructure <a class="header-anchor" href="#ocapi-infrastructure" aria-label="Permalink to &quot;OCAPI Infrastructure&quot;">​</a></h2><p>The OCAPI integration layer lives in <code>src/infrastructure/sfcc/</code> and consists of:</p><h3 id="apiclient-src-infrastructure-sfcc-apiclient-apiclient-js" tabindex="-1">ApiClient (<code>src/infrastructure/sfcc/ApiClient/ApiClient.js</code>) <a class="header-anchor" href="#apiclient-src-infrastructure-sfcc-apiclient-apiclient-js" aria-label="Permalink to &quot;ApiClient (`src/infrastructure/sfcc/ApiClient/ApiClient.js`)&quot;">​</a></h3><p>Central HTTP client for all OCAPI requests. Handles:</p><ul><li><strong>OAuth 2.0:</strong> Injects <code>Bearer</code> token via <code>AuthService</code>; auto-refreshes on 401.</li><li><strong>Rate limiting:</strong> <code>RateLimiter</code> enforces <code>maxConcurrent</code> (3) and <code>minTimeMs</code> (100ms) pacing.</li><li><strong>Retry:</strong> Exponential backoff with jitter on 429/5xx, respecting <code>Retry-After</code> headers. Up to <code>maxRetries</code> (3) attempts.</li><li><strong>Bulk requests:</strong> <code>batch()</code> method runs requests as individual rate-limited calls (no OCAPI batch endpoint), chunked at 50 for orderly execution.</li><li><strong>Params:</strong> Query parameters are sorted alphabetically via a custom <code>paramsSerializer</code> (OCAPI best practice for cache key consistency).</li><li><strong>Correlation IDs:</strong> Every request is tagged with a correlation ID for tracing.</li></ul><h3 id="authservice-src-infrastructure-sfcc-apiclient-authservice-js" tabindex="-1">AuthService (<code>src/infrastructure/sfcc/ApiClient/AuthService.js</code>) <a class="header-anchor" href="#authservice-src-infrastructure-sfcc-apiclient-authservice-js" aria-label="Permalink to &quot;AuthService (`src/infrastructure/sfcc/ApiClient/AuthService.js`)&quot;">​</a></h3><p>Singleton that manages OAuth client-credentials tokens:</p><ul><li><strong>In-memory + disk cache:</strong> Tokens are stored in memory and persisted to <code>dev-env/.token-cache.json</code> for reuse across CLI invocations.</li><li><strong>Safety window:</strong> Tokens are refreshed 60 seconds before expiry.</li><li><strong>Retry:</strong> Token fetch retries up to 4 times with exponential backoff.</li></ul><h3 id="ratelimiter-src-infrastructure-sfcc-apiclient-ratelimiter-js" tabindex="-1">RateLimiter (<code>src/infrastructure/sfcc/ApiClient/RateLimiter.js</code>) <a class="header-anchor" href="#ratelimiter-src-infrastructure-sfcc-apiclient-ratelimiter-js" aria-label="Permalink to &quot;RateLimiter (`src/infrastructure/sfcc/ApiClient/RateLimiter.js`)&quot;">​</a></h3><p>Concurrency and pacing controller:</p><ul><li>Limits active requests to <code>maxConcurrent</code>.</li><li>Enforces <code>minTimeMs</code> spacing between request starts.</li><li>Queues excess requests until a slot opens.</li></ul><h3 id="servicecache-src-infrastructure-sfcc-apiclient-servicecache-js" tabindex="-1">serviceCache (<code>src/infrastructure/sfcc/ApiClient/serviceCache.js</code>) <a class="header-anchor" href="#servicecache-src-infrastructure-sfcc-apiclient-servicecache-js" aria-label="Permalink to &quot;serviceCache (`src/infrastructure/sfcc/ApiClient/serviceCache.js`)&quot;">​</a></h3><p>Factory for TTL-based in-memory caches used by OCAPI services:</p><ul><li><code>createServiceCache(ttlMs)</code> returns a cache object with <code>has</code>, <code>get</code>, <code>set</code>, <code>isValid</code>, <code>clear</code>, <code>getStats</code>.</li><li>Default TTL: 5 minutes (<code>OCAPI_RUNTIME.cacheTtlMs</code>).</li><li>Used by <code>AssetService</code> and <code>SlotService</code> to avoid redundant OCAPI fetches within a session.</li></ul><h3 id="ocapierror-src-infrastructure-sfcc-apiclient-ocapierror-js" tabindex="-1">OcapiError (<code>src/infrastructure/sfcc/ApiClient/OcapiError.js</code>) <a class="header-anchor" href="#ocapierror-src-infrastructure-sfcc-apiclient-ocapierror-js" aria-label="Permalink to &quot;OcapiError (`src/infrastructure/sfcc/ApiClient/OcapiError.js`)&quot;">​</a></h3><p>Error class wrapping OCAPI HTTP errors with <code>status</code>, <code>message</code>, <code>response</code>, <code>endpoint</code>, and <code>correlationId</code>.</p><h2 id="ocapi-services-src-infrastructure-sfcc-ocapiservices" tabindex="-1">OCAPI Services (<code>src/infrastructure/sfcc/OcapiServices/</code>) <a class="header-anchor" href="#ocapi-services-src-infrastructure-sfcc-ocapiservices" aria-label="Permalink to &quot;OCAPI Services (`src/infrastructure/sfcc/OcapiServices/`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Service</th><th>Purpose</th><th>Key methods</th></tr></thead><tbody><tr><td><code>AssetService</code></td><td>Content asset CRUD + search</td><td><code>fetch</code>, <code>fetchMany</code>, <code>save</code>, <code>search</code>, <code>delete</code></td></tr><tr><td><code>CampaignService</code></td><td>Campaign CRUD</td><td><code>fetchById</code>, <code>exists</code>, <code>save</code>, <code>delete</code></td></tr><tr><td><code>SlotService</code></td><td>Slot config + campaign binding</td><td><code>getSlotConfiguration</code>, <code>save</code>, <code>bindToCampaign</code>, <code>searchSlotConfigurations</code></td></tr><tr><td><code>ReplicationService</code></td><td>Staging-to-production tracking</td><td><code>getReplicationStatus</code></td></tr></tbody></table><p>All services are barrel-exported from <code>src/infrastructure/sfcc/OcapiServices/index.js</code>.</p>',21)])])}const h=c(a,[["render",s]]);export{p as __pageData,h as default};
